mapper.select:
select date_list.date, `order`.num as order_num, contract.num as contract_num from ( select * from (values
row(#{item})
) t(date) ) date_list
left join ( select date_format(create_time, '%Y-%m') as date, count(*) as num from wf_form where date_format(create_time, '%Y-%m') between date_format(#{startTime}, '%Y-%m') and date_format(#{endTime} , '%Y-%m') and flag = 1 and tenant_id = 1
and current_org_id = #{orgId}
and content->'$.area' like #{area}
group by date_format(create_time, '%Y-%m') ) `order` on `order`.date = date_list.date
left join ( select date_format(ssc.create_time, '%Y-%m') as date, count(*) as num from sc_service_contract ssc
join wf_form wf ON ssc.form_id = wf.form_id AND wf.flag = 1 and wf.tenant_id = 1
where date_format(ssc.create_time, '%Y-%m') between date_format(#{startTime}, '%Y-%m') and date_format(#{endTime} , '%Y-%m') and ssc.flag = 1 and ssc.tenant_id = 1
and ssc.service_unit = #{orgId}
and wf.content->'$.area' like #{area}
group by date_format(ssc.create_time, '%Y-%m') ) contract on contract.date = date_list.date
